  "לֹא, זֶה קָרוֹב מְאֹד, חָמֵשׁ דַּקּוֹת בְּרֶגֶל.": "audio/he_eab6f846d4bb.mp3",
  "אֵיפֹה הַשֵּׁרוּתִים בְּבַקָּשָׁה?": "audio/he_4b3c096a83e1.mp3",
  "אֲנִי צָרִיךְ לְהַגִּיעַ לִירוּשָׁלַיִם.": "audio/he_e7dbe9d9294c.mp3",
  "מָתַי יוֹצֵא הָאוֹטוֹבּוּס הַבָּא?": "audio/he_91f532f707c8.mp3",
  "כַּמָּה זֶה עוֹלֶה?": "audio/he_5f54bba14d74.mp3",
  "אֶפְשָׁר לְשַׁלֵּם בְּכַרְטִיס אַשְׁרַאי?": "audio/he_11d4e0662468.mp3",
  "זֶה קְצָת יָקָר מִדַּי.": "audio/he_4d70ed34edb1.mp3",
  "אֲנִי רַק מִסְתַּכֵּל, תּוֹדָה.": "audio/he_2ce2405f9c8d.mp3",
  "יֵשׁ לָכֶם מִדָּה גְּדוֹלָה יוֹתֵר?": "audio/he_20ddc2b53e2b.mp3",
  "אֶפְשָׁר שַׂקִּית בְּבַקָּשָׁה?": "audio/he_92a0b0a3d013.mp3",
  "אֶפְשָׁר קַבָּלָה בְּבַקָּשָׁה?": "audio/he_3ff1a55786de.mp3",
  "הַחֲנוּת פְּתוּחָה עַד שָׁעָה תֵּשַׁע.": "audio/he_538ff2d0611f.mp3",
  "יֵשׁ לִי הַזְמָנָה עַל שֵׁם...": "audio/he_6612b16beb04.mp3",
  "מָה הַסִּיסְמָה שֶׁל הַוַּויְיפַאי?": "audio/he_93082884f40d.mp3",
  "הִנֵּה הַדַּרְכּוֹן שֶׁלִּי.": "audio/he_c8253c652f0f.mp3",
  "מָתַי מֻגֶּשֶׁת אֲרוּחַת הַבֹּקֶר?": "audio/he_090fc3e99afc.mp3",
  "אֵיפֹה שַׁעַר הָעֲלִיָּה לַמָּטוֹס?": "audio/he_52da9957ff64.mp3",
  "הַמִּזְוָדָה שֶׁלִּי לֹא הִגִּיעָה.": "audio/he_b87e687f71ce.mp3",
  "אֲנִי לוֹמֵד עִבְרִית לְאַט לְאַט.": "audio/he_bca77ebb6ee3.mp3",
  "אֶפְשָׁר לְדַבֵּר יוֹתֵר לְאַט, בְּבַקָּשָׁה?": "audio/he_4f2434b7a7f6.mp3",
  "לֹא הֵבַנְתִּי, אֶפְשָׁר שׁוּב?": "audio/he_6f897d42bded.mp3",
  "אֵיךְ אוֹמְרִים אֶת זֶה בְּעִבְרִית?": "audio/he_783e14bb1438.mp3",
  "מָה זֹאת אוֹמֶרֶת?": "audio/he_544c3da6104d.mp3",
  "כָּל הַכָּבוֹד! הָעִבְרִית שֶׁלְּךָ מְצֻיֶּנֶת.": "audio/he_fe7c64d895b1.mp3",
